+fn run_add(args: AddArgs) -> Result<(), ZoxideError> {
+    let config = load_runtime_config()?;
+    let maxage = load_maxage()?;
+    let delta = args.score.unwrap_or(1.0);
+    let now = now_secs();
+
+    let mut normalized = Vec::new();
+    for path in &args.paths {
+        let lookup_path = normalize_for_lookup(path)?;
+        if path_matches_any(&config.exclude_patterns, &lookup_path) {
+            continue;
+        }
+
+        if !path.is_dir() {
+            return Err(ZoxideError::simple(
+                1,
+                format!("zoxide: not a directory: {}", path.display()),
+            ));
+        }
+
+        normalized.push(normalize_for_storage(path, config.resolve_symlinks)?);
+    }
+
+    if normalized.is_empty() {
+        return Ok(());
+    }
+
+    let db_file = config.data_file();
+    let (mut database, _) = load_database(&db_file)?;
+    for path in normalized {
+        apply_add(&mut database, path, delta, now);
+    }
+    age_entries(&mut database.entries, maxage);
+    save_database(&db_file, &database)
