+            let db_file = config.data_file();
+            let (mut database, _) = load_database(&db_file)?;
+            let now = now_secs();
+            if let Some(index) = find_index(&database.entries, &path) {
+                database.entries[index].rank = (database.entries[index].rank - 1.0).max(0.0);
+            } else {
+                database.entries.push(Entry {
+                    path,
+                    rank: 0.0,
+                    last_access: now,
+                });
+            }
+            age_entries(&mut database.entries, maxage);
