+    match output.status.code() {
+        Some(0) => Ok(()),
+        Some(1) => Err(ZoxideError::simple(1, "zoxide: no match found")),
+        Some(130) => process::exit(130),
+        Some(code) => process::exit(code),
+        None => Ok(()),
+    }
+}
