+fn parse_z_import(input: &str) -> Result<Vec<Entry>, ZoxideError> {
+    let mut entries = Vec::new();
+    for line in input.lines() {
+        if line.is_empty() {
+            continue;
+        }
+        let parts: Vec<_> = line.split('|').collect();
+        if parts.len() != 3 {
+            return Err(ZoxideError::simple(
+                1,
+                format!("zoxide: import error\n\nCaused by:\n    invalid entry: {line}"),
+            ));
+        }
+        let rank = parts[1].parse::<f64>().map_err(|err| {
+            ZoxideError::new(
+                1,
+                format!(
+                    "zoxide: import error\n\nCaused by:\n    0: invalid rank: {}\n    1: {err}\n",
+                    parts[1]
+                ),
