+        })?;
+        let epoch = parts[2].parse::<u64>().map_err(|err| {
+            ZoxideError::new(
+                1,
+                format!(
+                    "zoxide: import error\n\nCaused by:\n    0: invalid epoch: {}\n    1: {err}\n",
+                    parts[2]
+                ),
+            )
+        })?;
+        entries.push(Entry {
+            path: parts[0].to_owned(),
+            rank,
+            last_access: epoch,
+        });
+    }
+    Ok(entries)
+}
+
+fn parse_autojump_import(input: &str) -> Result<Vec<Entry>, ZoxideError> {
+    let mut entries = Vec::new();
+    for line in input.lines() {
+        if line.is_empty() {
+            continue;
+        }
+        let Some((rank_text, path)) = line.split_once('\t') else {
+            return Err(ZoxideError::simple(
+                1,
+                format!("zoxide: import error\n\nCaused by:\n    invalid entry: {line}"),
+            ));
+        };
+        let rank = rank_text.parse::<f64>().map_err(|err| {
+            ZoxideError::new(
+                1,
+                format!(
+                    "zoxide: import error\n\nCaused by:\n    0: invalid rank: {rank_text}\n    1: {err}\n",
+                ),
+            )
+        })?;
+        entries.push(Entry {
+            path: path.to_owned(),
+            rank: 1.0 / (1.0 + (-rank).exp()),
+            last_access: 0,
+        });
+    }
+    Ok(entries)
+}
