+fn query_candidates(
+    database: &Database,
+    keywords: &[String],
+    include_all: bool,
+    base_dir: Option<&str>,
+    exclude: Option<&str>,
+) -> Vec<db::Candidate> {
+    let lowered_keywords: Vec<String> = keywords.iter().map(|keyword| keyword.to_lowercase()).collect();
+    let entries = database.entries.iter().enumerate().filter(|(_, entry)| {
+        if !include_all && !Path::new(&entry.path).is_dir() {
+            return false;
+        }
+        if let Some(base_dir) = base_dir {
+            if !path_in_subtree(&entry.path, base_dir) {
+                return false;
+            }
+        }
+        if let Some(exclude) = exclude {
+            if entry.path == exclude {
+                return false;
+            }
+        }
+        matches_keywords(&entry.path, &lowered_keywords)
+    });
+    sorted_candidates(entries)
+}
+
+fn matches_keywords(path: &str, keywords: &[String]) -> bool {
+    if keywords.is_empty() {
+        return true;
+    }
+
+    let lowered_path = path.to_lowercase();
+    let components: Vec<&str> = lowered_path
+        .split('/')
+        .filter(|component| !component.is_empty())
+        .collect();
+
+    if keywords.len() == 1 {
+        let keyword = &keywords[0];
+        if keyword == "/" {
+            return true;
+        }
+        if keyword.contains('/') {
+            return matches_slash_keyword(&components, keyword);
+        }
+        return components
+            .last()
+            .is_some_and(|basename| basename.contains(keyword));
+    }
+
+    let mut position = 0usize;
+    for keyword in keywords {
+        let Some(found) = lowered_path[position..].find(keyword) else {
+            return false;
+        };
+        position += found + keyword.len();
+    }
+    true
+}
+
+fn matches_slash_keyword(components: &[&str], keyword: &str) -> bool {
+    let parts: Vec<&str> = keyword.split('/').collect();
+    let mut start = 0usize;
+    while start < parts.len() && parts[start].is_empty() {
+        start += 1;
+    }
+    let parts = &parts[start..];
+    if parts.is_empty() {
+        return true;
+    }
+
+    if parts[..parts.len().saturating_sub(1)]
+        .iter()
+        .any(|part| part.is_empty())
+    {
+        return false;
+    }
+
+    if parts.last() == Some(&"") {
+        let needed = parts.len() - 1;
+        if needed == 0 || components.len() < needed + 1 {
+            return false;
+        }
+        let start_index = components.len() - (needed + 1);
+        for (component, part) in components[start_index..start_index + needed]
+            .iter()
+            .zip(&parts[..needed])
+        {
+            if !component.ends_with(part) {
+                return false;
+            }
+        }
+        true
+    } else {
+        let needed = parts.len();
+        if components.len() < needed {
+            return false;
+        }
+        let start_index = components.len() - needed;
+        for (component, part) in components[start_index..start_index + needed - 1]
+            .iter()
+            .zip(&parts[..needed - 1])
+        {
+            if !component.ends_with(part) {
+                return false;
+            }
+        }
+        components
+            .last()
+            .is_some_and(|basename| basename.starts_with(parts[needed - 1]))
+    }
+}
+
+fn print_edit_rows(database: &Database) {
+    for candidate in sorted_candidates(database.entries.iter().enumerate()) {
+        print!("{:>6.1}\t{}\0", candidate.score, candidate.entry.path);
