use std::fs;
use std::io::{self, Read, Write};
use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use crate::error::ZoxideError;

const DB_VERSION: u32 = 3;

#[derive(Clone, Debug)]
pub struct Entry {
    pub path: String,
    pub rank: f64,
    pub last_access: u64,
}

#[derive(Clone, Debug, Default)]
pub struct Database {
    pub entries: Vec<Entry>,
}

#[derive(Clone, Debug)]
pub struct Candidate {
    pub index: usize,
    pub score: f64,
    pub entry: Entry,
}

pub fn load_database(path: &Path) -> Result<(Database, bool), ZoxideError> {
    match fs::File::open(path) {
        Ok(mut file) => {
            let mut bytes = Vec::new();
            file.read_to_end(&mut bytes)
                .map_err(|_| ZoxideError::simple(1, "zoxide: could not deserialize database: corrupted data"))?;
            Ok((deserialize(&bytes)?, true))
        }
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok((Database::default(), false)),
        Err(_) => Err(ZoxideError::simple(
            1,
            "zoxide: could not deserialize database: corrupted data",
        )),
    }
}

pub fn save_database(path: &Path, database: &Database) -> Result<(), ZoxideError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|_| ZoxideError::simple(1, "zoxide: could not save database"))?;
    }

    let tmp_name = format!(
        "tmp_{}_{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    );
    let tmp_path = path
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .join(tmp_name);

    let bytes = serialize(database);
    {
        let mut file =
            fs::File::create(&tmp_path).map_err(|_| ZoxideError::simple(1, "zoxide: could not save database"))?;
        file.write_all(&bytes)
            .map_err(|_| ZoxideError::simple(1, "zoxide: could not save database"))?;
        file.flush()
            .map_err(|_| ZoxideError::simple(1, "zoxide: could not save database"))?;
    }

    fs::rename(&tmp_path, path).map_err(|_| ZoxideError::simple(1, "zoxide: could not save database"))?;
    Ok(())
}

pub fn age_entries(entries: &mut Vec<Entry>, maxage: u64) {
    let total: f64 = entries.iter().map(|entry| entry.rank).sum();
    if total > maxage as f64 {
        let factor = 0.9 * maxage as f64 / total;
        for entry in entries.iter_mut() {
            entry.rank *= factor;
        }
        entries.retain(|entry| entry.rank >= 1.0);
    }
}

pub fn query_score(entry: &Entry, now: u64) -> f64 {
    let age = now.saturating_sub(entry.last_access);
    let multiplier = if age < 60 * 60 {
        4.0
    } else if age < 60 * 60 * 24 {
        2.0
    } else if age < 60 * 60 * 24 * 7 {
        0.5
    } else {
        0.25
    };
    entry.rank * multiplier
}

pub fn sorted_candidates<'a, I>(entries: I) -> Vec<Candidate>
where
    I: IntoIterator<Item = (usize, &'a Entry)>,
{
    let now = now_secs();
    let mut candidates: Vec<_> = entries
        .into_iter()
        .map(|(index, entry)| Candidate {
            index,
            score: query_score(entry, now),
            entry: entry.clone(),
        })
        .collect();

    candidates.sort_by(|left, right| {
        right
            .score
            .total_cmp(&left.score)
            .then(right.index.cmp(&left.index))
    });
    candidates
}

pub fn find_index(entries: &[Entry], path: &str) -> Option<usize> {
    entries.iter().position(|entry| entry.path == path)
}

pub fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn deserialize(bytes: &[u8]) -> Result<Database, ZoxideError> {
    if bytes.len() < 12 {
        return Err(ZoxideError::simple(
            1,
            "zoxide: could not deserialize database: corrupted data",
        ));
    }

    let version = u32::from_le_bytes(bytes[0..4].try_into().unwrap());
    if version != DB_VERSION {
        return Err(ZoxideError::simple(
            1,
            format!("zoxide: unsupported version (got {version}, supports {DB_VERSION})"),
        ));
    }

    let mut cursor = 4usize;
    let count = read_u64(bytes, &mut cursor)? as usize;
    let mut entries = Vec::with_capacity(count);
    for _ in 0..count {
        let path_len = read_u64(bytes, &mut cursor)? as usize;
        let path_bytes = take(bytes, &mut cursor, path_len)?;
        let path = String::from_utf8_lossy(path_bytes).into_owned();
        let rank = read_f64(bytes, &mut cursor)?;
        let last_access = read_u64(bytes, &mut cursor)?;
        entries.push(Entry {
            path,
            rank,
            last_access,
        });
    }

    if cursor != bytes.len() {
        return Err(ZoxideError::simple(
            1,
            "zoxide: could not deserialize database: corrupted data",
        ));
    }

    Ok(Database { entries })
}

fn serialize(database: &Database) -> Vec<u8> {
    let mut bytes = Vec::new();
    bytes.extend_from_slice(&DB_VERSION.to_le_bytes());
    bytes.extend_from_slice(&(database.entries.len() as u64).to_le_bytes());
    for entry in &database.entries {
        let path_bytes = entry.path.as_bytes();
        bytes.extend_from_slice(&(path_bytes.len() as u64).to_le_bytes());
        bytes.extend_from_slice(path_bytes);
        bytes.extend_from_slice(&entry.rank.to_le_bytes());
        bytes.extend_from_slice(&entry.last_access.to_le_bytes());
    }
    bytes
}

fn read_u64(bytes: &[u8], cursor: &mut usize) -> Result<u64, ZoxideError> {
    let slice = take(bytes, cursor, 8)?;
    Ok(u64::from_le_bytes(slice.try_into().unwrap()))
}

fn read_f64(bytes: &[u8], cursor: &mut usize) -> Result<f64, ZoxideError> {
    let slice = take(bytes, cursor, 8)?;
    Ok(f64::from_le_bytes(slice.try_into().unwrap()))
}

fn take<'a>(bytes: &'a [u8], cursor: &mut usize, len: usize) -> Result<&'a [u8], ZoxideError> {
    let end = cursor.saturating_add(len);
    if end > bytes.len() {
        return Err(ZoxideError::simple(
            1,
            "zoxide: could not deserialize database: corrupted data",
        ));
    }
    let slice = &bytes[*cursor..end];
    *cursor = end;
    Ok(slice)
}

