use std::env;
use std::path::{Component, Path, PathBuf};

use crate::error::{ResultExt, ZoxideError};

#[derive(Clone, Debug)]
pub struct RuntimeConfig {
    pub data_dir: PathBuf,
    pub resolve_symlinks: bool,
    pub echo: bool,
    pub exclude_patterns: Vec<String>,
}

impl RuntimeConfig {
    pub fn data_file(&self) -> PathBuf {
        self.data_dir.join("db.zo")
    }
}

pub fn load_runtime_config() -> Result<RuntimeConfig, ZoxideError> {
    let data_dir = load_data_dir()?;
    let resolve_symlinks = env::var("_ZO_RESOLVE_SYMLINKS").ok().as_deref() == Some("1");
    let echo = env::var("_ZO_ECHO").ok().as_deref() == Some("1");
    let exclude_patterns = load_exclude_patterns();

    Ok(RuntimeConfig {
        data_dir,
        resolve_symlinks,
        echo,
        exclude_patterns,
    })
}

pub fn load_maxage() -> Result<u64, ZoxideError> {
    match env::var("_ZO_MAXAGE") {
        Ok(value) => value.parse::<u64>().map_err(|err| {
            ZoxideError::new(
                1,
                format!(
                    "zoxide: unable to parse _ZO_MAXAGE as integer: {value}\n\nCaused by:\n    {err}\n"
                ),
            )
        }),
        Err(_) => Ok(10_000),
    }
}

pub fn normalize_for_lookup(path: &Path) -> Result<String, ZoxideError> {
    let absolute = make_absolute(path)?;
    Ok(path_to_string(&normalize_lexical(&absolute)))
}

pub fn normalize_for_storage(path: &Path, resolve_symlinks: bool) -> Result<String, ZoxideError> {
    let absolute = make_absolute(path)?;
    if resolve_symlinks {
        let resolved = absolute.canonicalize().to_zoxide("zoxide: not a directory")?;
        Ok(path_to_string(&resolved))
    } else {
        Ok(path_to_string(&normalize_lexical(&absolute)))
    }
}

pub fn path_matches_any(patterns: &[String], path: &str) -> bool {
    patterns.iter().any(|pattern| wildcard_match(pattern, path))
}

pub fn path_in_subtree(path: &str, base_dir: &str) -> bool {
    path == base_dir
        || path
            .strip_prefix(base_dir)
            .is_some_and(|suffix| suffix.starts_with('/'))
}

fn load_data_dir() -> Result<PathBuf, ZoxideError> {
    if let Ok(data_dir) = env::var("_ZO_DATA_DIR") {
        let path = PathBuf::from(data_dir);
        if !path.is_absolute() {
            return Err(ZoxideError::simple(1, "zoxide: _ZO_DATA_DIR must be an absolute path"));
        }
        return Ok(path);
    }

    if let Ok(xdg_data_home) = env::var("XDG_DATA_HOME") {
        if !xdg_data_home.is_empty() {
            return Ok(PathBuf::from(xdg_data_home).join("zoxide"));
        }
    }

    if let Ok(home) = env::var("HOME") {
        if !home.is_empty() {
            return Ok(PathBuf::from(home).join(".local/share/zoxide"));
        }
    }

    Ok(env::current_dir()
        .to_zoxide("zoxide: could not determine current directory")?
        .join(".local/share/zoxide"))
}

fn load_exclude_patterns() -> Vec<String> {
    if let Ok(patterns) = env::var("_ZO_EXCLUDE_DIRS") {
        return patterns
            .split(':')
            .filter(|pattern| !pattern.is_empty())
            .map(ToOwned::to_owned)
            .collect();
    }

    match env::var("HOME") {
        Ok(home) if !home.is_empty() => vec![home],
        _ => Vec::new(),
    }
}

fn make_absolute(path: &Path) -> Result<PathBuf, ZoxideError> {
    if path.is_absolute() {
        return Ok(path.to_path_buf());
    }

    Ok(env::current_dir()
        .to_zoxide("zoxide: could not determine current directory")?
        .join(path))
}

fn normalize_lexical(path: &Path) -> PathBuf {
    let mut normalized = PathBuf::new();

    for component in path.components() {
        match component {
            Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
            Component::RootDir => normalized.push(component.as_os_str()),
            Component::CurDir => {}
            Component::ParentDir => {
                let _ = normalized.pop();
            }
            Component::Normal(part) => normalized.push(part),
        }
    }

    normalized
}

fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn wildcard_match(pattern: &str, text: &str) -> bool {
    let pattern = pattern.as_bytes();
    let text = text.as_bytes();
    let mut p = 0usize;
    let mut t = 0usize;
    let mut star = None;
    let mut star_match = 0usize;

    while t < text.len() {
        if p < pattern.len() && (pattern[p] == text[t] || pattern[p] == b'?') {
            p += 1;
            t += 1;
        } else if p < pattern.len() && pattern[p] == b'*' {
            star = Some(p);
            p += 1;
            star_match = t;
        } else if let Some(star_pos) = star {
            p = star_pos + 1;
            star_match += 1;
            t = star_match;
        } else {
            return false;
        }
    }

    while p < pattern.len() && pattern[p] == b'*' {
        p += 1;
    }

    p == pattern.len()
}

