mod config;
mod db;
mod error;
mod init;

use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{self, Command, Stdio};

use crate::config::{
    load_maxage, load_runtime_config, normalize_for_lookup, normalize_for_storage, path_in_subtree,
    path_matches_any,
};
use crate::db::{age_entries, find_index, load_database, now_secs, save_database, sorted_candidates, Database, Entry};
use crate::error::ZoxideError;

const VERSION: &str = "0.9.9";
const AUTHOR_BLOCK: &str = "Ajeet D'Souza <98ajeet@gmail.com>\nhttps://github.com/ajeetdsouza/zoxide";
const ABOUT: &str = "A smarter cd command for your terminal";
const ENV_VARS: &str = "Environment variables:\n  _ZO_DATA_DIR          Path for zoxide data files\n  _ZO_ECHO              Print the matched directory before navigating to it when set to 1\n  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded\n  _ZO_FZF_OPTS          Custom flags to pass to fzf\n  _ZO_MAXAGE            Maximum total age after which entries start getting deleted\n  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths";

#[derive(Clone, Debug)]
struct AddArgs {
    score: Option<f64>,
    paths: Vec<PathBuf>,
}

#[derive(Clone, Debug)]
struct EditArgs {
    action: Option<EditAction>,
}

#[derive(Clone, Debug)]
enum EditAction {
    Reload,
    Delete { path: String },
    Increment { path: String },
    Decrement { path: String },
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
enum ImportSource {
    Autojump,
    Z,
}

#[derive(Clone, Debug)]
struct ImportArgs {
    from: ImportSource,
    merge: bool,
    path: PathBuf,
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
enum Hook {
    None,
    Prompt,
    Pwd,
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
enum Shell {
    Bash,
    Elvish,
    Fish,
    Nushell,
    Posix,
    Powershell,
    Tcsh,
    Xonsh,
    Zsh,
}

#[derive(Clone, Debug)]
struct InitArgs {
    no_cmd: bool,
    cmd: String,
    hook: Hook,
    shell: Shell,
}

#[derive(Clone, Debug)]
struct QueryArgs {
    all: bool,
    interactive: bool,
    list: bool,
    score: bool,
    exclude: Option<PathBuf>,
    base_dir: Option<PathBuf>,
    keywords: Vec<String>,
}

#[derive(Clone, Debug)]
struct RemoveArgs {
    paths: Vec<PathBuf>,
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let outcome = dispatch(args);
    match outcome {
        Ok(code) => process::exit(code),
        Err(err) => {
            let _ = io::stderr().write_all(err.message.as_bytes());
            process::exit(err.code);
        }
    }
}

fn dispatch(args: Vec<String>) -> Result<i32, ZoxideError> {
    if args.is_empty() {
        return Err(ZoxideError::simple(2, top_help()));
    }

    match args[0].as_str() {
        "-h" | "--help" => {
            print!("{}", top_help());
            Ok(0)
        }
        "-V" | "--version" => {
            println!("zoxide {VERSION}");
            Ok(0)
        }
        "add" => handle_add(&args[1..]),
        "edit" => handle_edit(&args[1..]),
        "import" => handle_import(&args[1..]),
        "init" => handle_init(&args[1..]),
        "query" => handle_query(&args[1..]),
        "remove" => handle_remove(&args[1..]),
        other => Err(ZoxideError::simple(
            2,
            format!(
                "error: unrecognized subcommand '{other}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'."
            ),
        )),
    }
}

fn handle_add(args: &[String]) -> Result<i32, ZoxideError> {
    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
        print!("{}", add_help());
        return Ok(0);
    }
    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        println!("zoxide-add {VERSION}");
        return Ok(0);
    }

    let parsed = parse_add_args(args)?;
    run_add(parsed)?;
    Ok(0)
}

fn handle_edit(args: &[String]) -> Result<i32, ZoxideError> {
    if args.is_empty() {
        run_edit(EditArgs { action: None })?;
        return Ok(0);
    }
    if args[0] == "-h" || args[0] == "--help" {
        print!("{}", edit_help());
        return Ok(0);
    }
    if args[0] == "-V" || args[0] == "--version" {
        println!("zoxide-edit {VERSION}");
        return Ok(0);
    }

    match args[0].as_str() {
        "reload" => {
            if args.len() > 1 && (args[1] == "-h" || args[1] == "--help") {
                print!("{}", "Usage: executable edit reload\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n");
                return Ok(0);
            }
            if args.len() > 1 && (args[1] == "-V" || args[1] == "--version") {
                println!("zoxide-edit-reload {VERSION}");
                return Ok(0);
            }
            run_edit(EditArgs {
                action: Some(EditAction::Reload),
            })?;
            Ok(0)
        }
        "delete" | "increment" | "decrement" => {
            if args.len() == 2 && (args[1] == "-h" || args[1] == "--help") {
                print!(
                    "{}",
                    format!(
                        "Usage: executable edit {} <PATH>\n\nArguments:\n  <PATH>  \n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n",
                        args[0]
                    )
                );
                return Ok(0);
            }
            if args.len() == 2 && (args[1] == "-V" || args[1] == "--version") {
                println!("zoxide-edit-{} {VERSION}", args[0]);
                return Ok(0);
            }
            if args.len() != 2 {
                return Err(ZoxideError::simple(
                    2,
                    format!(
                        "error: the following required arguments were not provided:\n  <PATH>\n\nUsage: executable edit {} <PATH>\n\nFor more information, try '--help'.",
                        args[0]
                    ),
                ));
            }
            let action = match args[0].as_str() {
                "delete" => EditAction::Delete {
                    path: args[1].clone(),
                },
                "increment" => EditAction::Increment {
                    path: args[1].clone(),
                },
                _ => EditAction::Decrement {
                    path: args[1].clone(),
                },
            };
            run_edit(EditArgs {
                action: Some(action),
            })?;
            Ok(0)
        }
        _ => Err(ZoxideError::simple(
            2,
            "error: unexpected argument found\n\nUsage: executable edit\n\nFor more information, try '--help'.",
        )),
    }
}

fn handle_import(args: &[String]) -> Result<i32, ZoxideError> {
    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
        print!("{}", import_help());
        return Ok(0);
    }
    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        println!("zoxide-import {VERSION}");
        return Ok(0);
    }

    let parsed = parse_import_args(args)?;
    run_import(parsed)?;
    Ok(0)
}

fn handle_init(args: &[String]) -> Result<i32, ZoxideError> {
    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
        print!("{}", init_help());
        return Ok(0);
    }
    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        println!("zoxide-init {VERSION}");
        return Ok(0);
    }

    let parsed = parse_init_args(args)?;
    run_init(parsed)?;
    Ok(0)
}

fn handle_query(args: &[String]) -> Result<i32, ZoxideError> {
    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
        print!("{}", query_help());
        return Ok(0);
    }
    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        println!("zoxide-query {VERSION}");
        return Ok(0);
    }

    let parsed = parse_query_args(args)?;
    run_query(parsed)
}

fn handle_remove(args: &[String]) -> Result<i32, ZoxideError> {
    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
        print!("{}", remove_help());
        return Ok(0);
    }
    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        println!("zoxide-remove {VERSION}");
        return Ok(0);
    }

    run_remove(RemoveArgs {
        paths: args.iter().map(PathBuf::from).collect(),
    })?;
    Ok(0)
}

fn parse_add_args(args: &[String]) -> Result<AddArgs, ZoxideError> {
    let mut score = None;
    let mut paths = Vec::new();
    let mut i = 0usize;

    while i < args.len() {
        match args[i].as_str() {
            "-s" | "--score" => {
                i += 1;
                let Some(value) = args.get(i) else {
                    return Err(ZoxideError::simple(
                        2,
                        "error: a value is required for '--score <SCORE>' but none was supplied\n\nFor more information, try '--help'.",
                    ));
                };
                if value.starts_with('-') {
                    return Err(ZoxideError::simple(
                        2,
                        format!(
                            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable add [OPTIONS] <PATHS>...\n\nFor more information, try '--help'.",
                            value, value, value
                        ),
                    ));
                }
                score = Some(value.parse::<f64>().map_err(|_| {
                    ZoxideError::simple(
                        2,
                        format!(
                            "error: invalid value '{}' for '--score <SCORE>': invalid float literal\n\nFor more information, try '--help'.",
                            value
                        ),
                    )
                })?);
            }
            value if value.starts_with("--score=") => {
                let raw = &value["--score=".len()..];
                score = Some(raw.parse::<f64>().map_err(|_| {
                    ZoxideError::simple(
                        2,
                        format!(
                            "error: invalid value '{}' for '--score <SCORE>': invalid float literal\n\nFor more information, try '--help'.",
                            raw
                        ),
                    )
                })?);
            }
            value if value.starts_with('-') => {
                return Err(ZoxideError::simple(
                    2,
                    format!(
                        "error: unexpected argument '{}' found\n\nUsage: executable add [OPTIONS] <PATHS>...\n\nFor more information, try '--help'.",
                        value
                    ),
                ));
            }
            value => paths.push(PathBuf::from(value)),
        }
        i += 1;
    }

    if paths.is_empty() {
        return Err(ZoxideError::simple(
            2,
            "error: the following required arguments were not provided:\n  <PATHS>...\n\nUsage: executable add <PATHS>...\n\nFor more information, try '--help'.",
        ));
    }

    Ok(AddArgs { score, paths })
}

fn parse_import_args(args: &[String]) -> Result<ImportArgs, ZoxideError> {
    let mut from = None;
    let mut merge = false;
    let mut path = None;
    let mut i = 0usize;

    while i < args.len() {
        match args[i].as_str() {
            "--from" => {
                i += 1;
                let Some(value) = args.get(i) else {
                    return Err(ZoxideError::simple(
                        2,
                        "error: a value is required for '--from <FROM>' but none was supplied\n\nFor more information, try '--help'.",
                    ));
                };
                from = Some(parse_import_source(value)?);
            }
            value if value.starts_with("--from=") => {
                from = Some(parse_import_source(&value["--from=".len()..])?);
            }
            "--merge" => merge = true,
            value if value.starts_with('-') => {
                return Err(ZoxideError::simple(
                    2,
                    format!(
                        "error: unexpected argument '{}' found\n\nUsage: executable import [OPTIONS] --from <FROM> <PATH>\n\nFor more information, try '--help'.",
                        value
                    ),
                ));
            }
            value => {
                if path.is_some() {
                    return Err(ZoxideError::simple(
                        2,
                        format!(
                            "error: unexpected argument '{}' found\n\nUsage: executable import [OPTIONS] --from <FROM> <PATH>\n\nFor more information, try '--help'.",
                            value
                        ),
                    ));
                }
                path = Some(PathBuf::from(value));
            }
        }
        i += 1;
    }

    let from = from.ok_or_else(|| {
        ZoxideError::simple(
            2,
            "error: the following required arguments were not provided:\n  --from <FROM>\n  <PATH>\n\nUsage: executable import [OPTIONS] --from <FROM> <PATH>\n\nFor more information, try '--help'.",
        )
    })?;
    let path = path.ok_or_else(|| {
        ZoxideError::simple(
            2,
            "error: the following required arguments were not provided:\n  --from <FROM>\n  <PATH>\n\nUsage: executable import [OPTIONS] --from <FROM> <PATH>\n\nFor more information, try '--help'.",
        )
    })?;

    Ok(ImportArgs { from, merge, path })
}

fn parse_init_args(args: &[String]) -> Result<InitArgs, ZoxideError> {
    let mut no_cmd = false;
    let mut cmd = "z".to_owned();
    let mut hook = Hook::Pwd;
    let mut shell = None;
    let mut i = 0usize;

    while i < args.len() {
        match args[i].as_str() {
            "--no-cmd" => no_cmd = true,
            "--cmd" => {
                i += 1;
                let Some(value) = args.get(i) else {
                    return Err(ZoxideError::simple(
                        2,
                        "error: a value is required for '--cmd <CMD>' but none was supplied\n\nFor more information, try '--help'.",
                    ));
                };
                cmd = value.clone();
            }
            value if value.starts_with("--cmd=") => cmd = value["--cmd=".len()..].to_owned(),
            "--hook" => {
                i += 1;
                let Some(value) = args.get(i) else {
                    return Err(ZoxideError::simple(
                        2,
                        "error: a value is required for '--hook <HOOK>' but none was supplied\n\nFor more information, try '--help'.",
                    ));
                };
                hook = parse_hook(value)?;
            }
            value if value.starts_with("--hook=") => hook = parse_hook(&value["--hook=".len()..])?,
            value if value.starts_with('-') => {
                return Err(ZoxideError::simple(
                    2,
                    format!(
                        "error: unexpected argument '{}' found\n\nUsage: executable init [OPTIONS] <SHELL>\n\nFor more information, try '--help'.",
                        value
                    ),
                ));
            }
            value => {
                if shell.is_some() {
                    return Err(ZoxideError::simple(
                        2,
                        format!(
                            "error: unexpected argument '{}' found\n\nUsage: executable init [OPTIONS] <SHELL>\n\nFor more information, try '--help'.",
                            value
                        ),
                    ));
                }
                shell = Some(parse_shell(value)?);
            }
        }
        i += 1;
    }

    let shell = shell.ok_or_else(|| {
        ZoxideError::simple(
            2,
            "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: executable init <SHELL>\n\nFor more information, try '--help'.",
        )
    })?;

    Ok(InitArgs {
        no_cmd,
        cmd,
        hook,
        shell,
    })
}

fn parse_query_args(args: &[String]) -> Result<QueryArgs, ZoxideError> {
    let mut parsed = QueryArgs {
        all: false,
        interactive: false,
        list: false,
        score: false,
        exclude: None,
        base_dir: None,
        keywords: Vec::new(),
    };
    let mut i = 0usize;

    while i < args.len() {
        match args[i].as_str() {
            "-a" | "--all" => parsed.all = true,
            "-i" | "--interactive" => parsed.interactive = true,
            "-l" | "--list" => parsed.list = true,
            "-s" | "--score" => parsed.score = true,
            "--exclude" => {
                i += 1;
                let Some(value) = args.get(i) else {
                    return Err(ZoxideError::simple(
                        2,
                        "error: a value is required for '--exclude <path>' but none was supplied\n\nFor more information, try '--help'.",
                    ));
                };
                parsed.exclude = Some(PathBuf::from(value));
            }
            value if value.starts_with("--exclude=") => {
                parsed.exclude = Some(PathBuf::from(&value["--exclude=".len()..]));
            }
            "--base-dir" => {
                i += 1;
                let Some(value) = args.get(i) else {
                    return Err(ZoxideError::simple(
                        2,
                        "error: a value is required for '--base-dir <path>' but none was supplied\n\nFor more information, try '--help'.",
                    ));
                };
                parsed.base_dir = Some(PathBuf::from(value));
            }
            value if value.starts_with("--base-dir=") => {
                parsed.base_dir = Some(PathBuf::from(&value["--base-dir=".len()..]));
            }
            value if value.starts_with('-') => {
                return Err(ZoxideError::simple(
                    2,
                    format!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable query [OPTIONS] [KEYWORDS]...\n\nFor more information, try '--help'.",
                        value, value, value
                    ),
                ));
            }
            value => parsed.keywords.push(value.clone()),
        }
        i += 1;
    }

    if parsed.interactive && parsed.list {
        return Err(ZoxideError::simple(
            2,
            "error: the argument '--interactive' cannot be used with '--list'\n\nUsage: executable query --interactive <KEYWORDS>...\n\nFor more information, try '--help'.",
        ));
    }

    Ok(parsed)
}

fn parse_import_source(value: &str) -> Result<ImportSource, ZoxideError> {
    match value {
        "autojump" => Ok(ImportSource::Autojump),
        "z" => Ok(ImportSource::Z),
        _ => Err(ZoxideError::simple(
            2,
            format!(
                "error: invalid value '{}' for '--from <FROM>'\n  [possible values: autojump, z]\n\nFor more information, try '--help'.",
                value
            ),
        )),
    }
}

fn parse_hook(value: &str) -> Result<Hook, ZoxideError> {
    match value {
        "none" => Ok(Hook::None),
        "prompt" => Ok(Hook::Prompt),
        "pwd" => Ok(Hook::Pwd),
        _ => Err(ZoxideError::simple(
            2,
            format!(
                "error: invalid value '{}' for '--hook <HOOK>'\n  [possible values: none, prompt, pwd]\n\nFor more information, try '--help'.",
                value
            ),
        )),
    }
}

fn parse_shell(value: &str) -> Result<Shell, ZoxideError> {
    match value {
        "bash" => Ok(Shell::Bash),
        "elvish" => Ok(Shell::Elvish),
        "fish" => Ok(Shell::Fish),
        "nushell" => Ok(Shell::Nushell),
        "posix" => Ok(Shell::Posix),
        "powershell" => Ok(Shell::Powershell),
        "tcsh" => Ok(Shell::Tcsh),
        "xonsh" => Ok(Shell::Xonsh),
        "zsh" => Ok(Shell::Zsh),
        _ => Err(ZoxideError::simple(
            2,
            format!(
                "error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]\n\nFor more information, try '--help'.",
                value
            ),
        )),
    }
}

fn run_add(args: AddArgs) -> Result<(), ZoxideError> {
    let config = load_runtime_config()?;
    let maxage = load_maxage()?;
    let delta = args.score.unwrap_or(1.0);
    let now = now_secs();

    let mut normalized = Vec::new();
    for path in &args.paths {
        let lookup_path = normalize_for_lookup(path)?;
        if path_matches_any(&config.exclude_patterns, &lookup_path) {
            continue;
        }

        if !path.is_dir() {
            return Err(ZoxideError::simple(
                1,
                format!("zoxide: not a directory: {}", path.display()),
            ));
        }

        normalized.push(normalize_for_storage(path, config.resolve_symlinks)?);
    }

    if normalized.is_empty() {
        return Ok(());
    }

    let db_file = config.data_file();
    let (mut database, _) = load_database(&db_file)?;
    for path in normalized {
        apply_add(&mut database, path, delta, now);
    }
    age_entries(&mut database.entries, maxage);
    save_database(&db_file, &database)
}

fn run_remove(args: RemoveArgs) -> Result<(), ZoxideError> {
    let config = load_runtime_config()?;
    if args.paths.is_empty() {
        return Ok(());
    }

    let db_file = config.data_file();
    let (mut database, existed) = load_database(&db_file)?;
    let mut targets = Vec::new();
    for path in &args.paths {
        let normalized = normalize_for_lookup(path)?;
        if find_index(&database.entries, &normalized).is_none() {
            return Err(ZoxideError::simple(
                1,
                format!("zoxide: path not found in database: {normalized}"),
            ));
        }
        targets.push(normalized);
    }

    database.entries.retain(|entry| !targets.iter().any(|target| target == &entry.path));
    if existed || !database.entries.is_empty() {
        save_database(&db_file, &database)?;
    }
    Ok(())
}

fn run_import(args: ImportArgs) -> Result<(), ZoxideError> {
    let config = load_runtime_config()?;
    let maxage = load_maxage()?;
    let db_file = config.data_file();
    let (mut database, existed) = load_database(&db_file)?;

    if existed && !database.entries.is_empty() && !args.merge {
        return Err(ZoxideError::simple(
            1,
            "zoxide: current database is not empty, specify --merge to continue anyway",
        ));
    }

    let input = fs::read_to_string(&args.path).map_err(|err| {
        ZoxideError::new(
            1,
            format!(
                "zoxide: could not open database for importing: {}\n\nCaused by:\n    {err}\n",
                args.path.display()
            ),
        )
    })?;

    let imported = match args.from {
        ImportSource::Z => parse_z_import(&input)?,
        ImportSource::Autojump => parse_autojump_import(&input)?,
    };

    if imported.is_empty() {
        return Ok(());
    }

    if !args.merge {
        database.entries.clear();
    }

    for entry in imported {
        if let Some(index) = find_index(&database.entries, &entry.path) {
            let existing = &mut database.entries[index];
            existing.rank += entry.rank;
            existing.last_access = existing.last_access.max(entry.last_access);
        } else {
            database.entries.push(entry);
        }
    }

    age_entries(&mut database.entries, maxage);
    save_database(&db_file, &database)
}

fn run_init(args: InitArgs) -> Result<(), ZoxideError> {
    let config = load_runtime_config()?;
    let shell = shell_name(args.shell);
    let hook = hook_name(args.hook);
    let text = init::render(
        shell,
        hook,
        args.no_cmd,
        &args.cmd,
        config.echo,
        config.resolve_symlinks,
    )
    .ok_or_else(|| ZoxideError::simple(1, "zoxide: could not generate shell configuration"))?;

    print!("{text}");
    Ok(())
}

fn run_query(args: QueryArgs) -> Result<i32, ZoxideError> {
    let config = load_runtime_config()?;
    let db_file = config.data_file();
    let (database, _) = load_database(&db_file)?;
    let base_dir = match args.base_dir {
        Some(path) => Some(normalize_for_lookup(&path)?),
        None => None,
    };
    let exclude = match args.exclude {
        Some(path) => Some(normalize_for_lookup(&path)?),
        None => None,
    };

    let candidates = query_candidates(
        &database,
        &args.keywords,
        args.all,
        base_dir.as_deref(),
        exclude.as_deref(),
    );

    if args.interactive {
        run_query_interactive(candidates, args.score)?;
        return Ok(0);
    }

    if args.list {
        if args.score {
            for candidate in candidates {
                println!("{:>6.1} {}", candidate.score, candidate.entry.path);
            }
        } else {
            for candidate in candidates {
                println!("{}", candidate.entry.path);
            }
        }
        return Ok(0);
    }

    let Some(candidate) = candidates.into_iter().next() else {
        return Err(ZoxideError::simple(1, "zoxide: no match found"));
    };

    if args.score {
        println!("{:>6.1} {}", candidate.score, candidate.entry.path);
    } else {
        println!("{}", candidate.entry.path);
    }
    Ok(0)
}

fn run_query_interactive(candidates: Vec<db::Candidate>, include_score: bool) -> Result<(), ZoxideError> {
    let mut child = spawn_fzf(query_fzf_args())?;
    {
        let stdin = child.stdin.as_mut().expect("stdin is piped");
        for candidate in &candidates {
            write!(stdin, "{:>6.1}\t{}\0", candidate.score, candidate.entry.path)
                .map_err(|_| ZoxideError::simple(1, "zoxide: could not read selection from fzf"))?;
        }
    }

    let output = child
        .wait_with_output()
        .map_err(|_| ZoxideError::simple(1, "zoxide: could not read selection from fzf"))?;
    match output.status.code() {
        Some(130) => process::exit(130),
        Some(0) => {
            if output.stdout.is_empty() {
                return Err(ZoxideError::simple(1, "zoxide: could not read selection from fzf"));
            }
        }
        _ => return Err(ZoxideError::simple(1, "zoxide: could not read selection from fzf")),
    }

    let trimmed = output.stdout.strip_suffix(&[0]).unwrap_or(&output.stdout);
    let row = String::from_utf8_lossy(trimmed);
    if include_score {
        io::stdout()
            .write_all(trimmed)
            .map_err(|_| ZoxideError::simple(1, "zoxide: could not read selection from fzf"))?;
        io::stdout()
            .write_all(&[0])
            .map_err(|_| ZoxideError::simple(1, "zoxide: could not read selection from fzf"))?;
    } else {
        let path = row
            .split_once('\t')
            .map(|(_, path)| path)
            .unwrap_or(row.as_ref());
        io::stdout()
            .write_all(path.as_bytes())
            .map_err(|_| ZoxideError::simple(1, "zoxide: could not read selection from fzf"))?;
        io::stdout()
            .write_all(&[0])
            .map_err(|_| ZoxideError::simple(1, "zoxide: could not read selection from fzf"))?;
    }
    Ok(())
}

fn run_edit(args: EditArgs) -> Result<(), ZoxideError> {
    match args.action {
        Some(EditAction::Reload) => {
            let config = load_runtime_config()?;
            let db_file = config.data_file();
            let (database, _) = load_database(&db_file)?;
            print_edit_rows(&database);
            Ok(())
        }
        Some(EditAction::Delete { path }) => {
            let config = load_runtime_config()?;
            let db_file = config.data_file();
            let (mut database, existed) = load_database(&db_file)?;
            database.entries.retain(|entry| entry.path != path);
            if existed {
                save_database(&db_file, &database)?;
            }
            print_edit_rows(&database);
            Ok(())
        }
        Some(EditAction::Increment { path }) => {
            let config = load_runtime_config()?;
            let maxage = load_maxage()?;
            let db_file = config.data_file();
            let (mut database, _) = load_database(&db_file)?;
            let now = now_secs();
            if let Some(index) = find_index(&database.entries, &path) {
                database.entries[index].rank += 1.0;
            } else {
                database.entries.push(Entry {
                    path,
                    rank: 1.0,
                    last_access: now,
                });
            }
            age_entries(&mut database.entries, maxage);
            save_database(&db_file, &database)?;
            print_edit_rows(&database);
            Ok(())
        }
        Some(EditAction::Decrement { path }) => {
            let config = load_runtime_config()?;
            let maxage = load_maxage()?;
            let db_file = config.data_file();
            let (mut database, _) = load_database(&db_file)?;
            let now = now_secs();
            if let Some(index) = find_index(&database.entries, &path) {
                database.entries[index].rank = (database.entries[index].rank - 1.0).max(0.0);
            } else {
                database.entries.push(Entry {
                    path,
                    rank: 0.0,
                    last_access: now,
                });
            }
            age_entries(&mut database.entries, maxage);
            save_database(&db_file, &database)?;
            print_edit_rows(&database);
            Ok(())
        }
        None => run_edit_ui(),
    }
}

fn run_edit_ui() -> Result<(), ZoxideError> {
    let child = spawn_fzf(edit_fzf_args())?;
    let output = child
        .wait_with_output()
        .map_err(|_| ZoxideError::simple(1, "zoxide: no match found"))?;
    match output.status.code() {
        Some(0) => Ok(()),
        Some(1) => Err(ZoxideError::simple(1, "zoxide: no match found")),
        Some(130) => process::exit(130),
        Some(code) => process::exit(code),
        None => Ok(()),
    }
}

fn apply_add(database: &mut Database, path: String, delta: f64, now: u64) {
    let clamped_delta = delta.max(0.0);
    if let Some(index) = find_index(&database.entries, &path) {
        if delta > 0.0 {
            let mut entry = database.entries.remove(index);
            entry.rank += clamped_delta;
            entry.last_access = now;
            database.entries.push(entry);
        } else {
            let entry = &mut database.entries[index];
            entry.rank = (entry.rank + delta).max(0.0);
            entry.last_access = now;
        }
    } else {
        database.entries.push(Entry {
            path,
            rank: clamped_delta,
            last_access: now,
        });
    }
}

fn parse_z_import(input: &str) -> Result<Vec<Entry>, ZoxideError> {
    let mut entries = Vec::new();
    for line in input.lines() {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<_> = line.split('|').collect();
        if parts.len() != 3 {
            return Err(ZoxideError::simple(
                1,
                format!("zoxide: import error\n\nCaused by:\n    invalid entry: {line}"),
            ));
        }
        let rank = parts[1].parse::<f64>().map_err(|err| {
            ZoxideError::new(
                1,
                format!(
                    "zoxide: import error\n\nCaused by:\n    0: invalid rank: {}\n    1: {err}\n",
                    parts[1]
                ),
            )
        })?;
        let epoch = parts[2].parse::<u64>().map_err(|err| {
            ZoxideError::new(
                1,
                format!(
                    "zoxide: import error\n\nCaused by:\n    0: invalid epoch: {}\n    1: {err}\n",
                    parts[2]
                ),
            )
        })?;
        entries.push(Entry {
            path: parts[0].to_owned(),
            rank,
            last_access: epoch,
        });
    }
    Ok(entries)
}

fn parse_autojump_import(input: &str) -> Result<Vec<Entry>, ZoxideError> {
    let mut entries = Vec::new();
    for line in input.lines() {
        if line.is_empty() {
            continue;
        }
        let Some((rank_text, path)) = line.split_once('\t') else {
            return Err(ZoxideError::simple(
                1,
                format!("zoxide: import error\n\nCaused by:\n    invalid entry: {line}"),
            ));
        };
        let rank = rank_text.parse::<f64>().map_err(|err| {
            ZoxideError::new(
                1,
                format!(
                    "zoxide: import error\n\nCaused by:\n    0: invalid rank: {rank_text}\n    1: {err}\n",
                ),
            )
        })?;
        entries.push(Entry {
            path: path.to_owned(),
            rank: 1.0 / (1.0 + (-rank).exp()),
            last_access: 0,
        });
    }
    Ok(entries)
}

fn query_candidates(
    database: &Database,
    keywords: &[String],
    include_all: bool,
    base_dir: Option<&str>,
    exclude: Option<&str>,
) -> Vec<db::Candidate> {
    let lowered_keywords: Vec<String> = keywords.iter().map(|keyword| keyword.to_lowercase()).collect();
    let entries = database.entries.iter().enumerate().filter(|(_, entry)| {
        if !include_all && !Path::new(&entry.path).is_dir() {
            return false;
        }
        if let Some(base_dir) = base_dir {
            if !path_in_subtree(&entry.path, base_dir) {
                return false;
            }
        }
        if let Some(exclude) = exclude {
            if entry.path == exclude {
                return false;
            }
        }
        matches_keywords(&entry.path, &lowered_keywords)
    });
    sorted_candidates(entries)
}

fn matches_keywords(path: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() {
        return true;
    }

    let lowered_path = path.to_lowercase();
    let components: Vec<&str> = lowered_path
        .split('/')
        .filter(|component| !component.is_empty())
        .collect();

    if keywords.len() == 1 {
        let keyword = &keywords[0];
        if keyword == "/" {
            return true;
        }
        if keyword.contains('/') {
            return matches_slash_keyword(&components, keyword);
        }
        return components
            .last()
            .is_some_and(|basename| basename.contains(keyword));
    }

    let mut position = 0usize;
    for keyword in keywords {
        let Some(found) = lowered_path[position..].find(keyword) else {
            return false;
        };
        position += found + keyword.len();
    }
    true
}

fn matches_slash_keyword(components: &[&str], keyword: &str) -> bool {
    let parts: Vec<&str> = keyword.split('/').collect();
    let mut start = 0usize;
    while start < parts.len() && parts[start].is_empty() {
        start += 1;
    }
    let parts = &parts[start..];
    if parts.is_empty() {
        return true;
    }

    if parts[..parts.len().saturating_sub(1)]
        .iter()
        .any(|part| part.is_empty())
    {
        return false;
    }

    if parts.last() == Some(&"") {
        let needed = parts.len() - 1;
        if needed == 0 || components.len() < needed + 1 {
            return false;
        }
        let start_index = components.len() - (needed + 1);
        for (component, part) in components[start_index..start_index + needed]
            .iter()
            .zip(&parts[..needed])
        {
            if !component.ends_with(part) {
                return false;
            }
        }
        true
    } else {
        let needed = parts.len();
        if components.len() < needed {
            return false;
        }
        let start_index = components.len() - needed;
        for (component, part) in components[start_index..start_index + needed - 1]
            .iter()
            .zip(&parts[..needed - 1])
        {
            if !component.ends_with(part) {
                return false;
            }
        }
        components
            .last()
            .is_some_and(|basename| basename.starts_with(parts[needed - 1]))
    }
}

fn print_edit_rows(database: &Database) {
    for candidate in sorted_candidates(database.entries.iter().enumerate()) {
        print!("{:>6.1}\t{}\0", candidate.score, candidate.entry.path);
    }
}

fn spawn_fzf(args: &[&str]) -> Result<process::Child, ZoxideError> {
    Command::new("fzf")
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(|_| ZoxideError::simple(1, "zoxide: could not find fzf, is it installed?"))
}

